ALTER TABLE passagem_turno ADD COLUMN data_referencia DATE NULL COMMENT 'Dia do turno passado';
ALTER TABLE passagem_turno_paciente
  ADD COLUMN situacao_sbar VARCHAR(2000) NULL, ADD COLUMN historia_sbar VARCHAR(2000) NULL,
  ADD COLUMN avaliacao_sbar VARCHAR(2000) NULL, ADD COLUMN recomendacao_sbar VARCHAR(2000) NULL;
CREATE TABLE passagem_turno_pendencia (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, passagem_turno_paciente_id BIGINT UNSIGNED NOT NULL, sequencia SMALLINT UNSIGNED NOT NULL,
  descricao VARCHAR(500) NOT NULL, prazo_em DATETIME(3) NULL, resolvida BOOLEAN NOT NULL DEFAULT FALSE,
  criado_em DATETIME(3) NOT NULL, criado_por BIGINT UNSIGNED NULL, alterado_em DATETIME(3) NULL, alterado_por BIGINT UNSIGNED NULL, versao INT UNSIGNED NOT NULL DEFAULT 1, excluido_em DATETIME(3) NULL, excluido_por BIGINT UNSIGNED NULL,
  UNIQUE KEY uq_passagem_turno_pendencia_sequencia (passagem_turno_paciente_id, sequencia),
  CONSTRAINT fk_passagem_turno_pendencia_passagem_turno_paciente_id FOREIGN KEY (passagem_turno_paciente_id) REFERENCES passagem_turno_paciente (id) ON DELETE RESTRICT
) COMMENT='Pendência de cada paciente na passagem de plantão';
